<?php
namespace VanguardLTE\Http\Controllers\Web\Liteback;
use VanguardLTE\{StockAsset,StockPosition,StockRound}; use VanguardLTE\Http\Controllers\Controller; use VanguardLTE\Services\StockTradingService;
class StockTradingController extends Controller { public function index() { $assets=StockAsset::orderBy('symbol')->paginate(100); $rounds=StockRound::with('asset')->latest()->take(20)->get(); $positions=StockPosition::with(['user','asset','round'])->latest()->take(25)->get(); return view('liteback.stocks.index',compact('assets','rounds','positions')); } public function refresh(StockTradingService $stocks) { $result=$stocks->refreshCatalog(); if(($result['success']??false)!==true)return back()->withErrors(['stocks'=>$result['message']??'Stock catalog refresh failed.']); return back()->with('success',"Stock catalog refreshed. {$result['enabled']} of {$result['count']} cached symbols are enabled; the first refresh enables the top 20."); } public function toggle(StockAsset $asset) { $asset->update(['is_enabled'=>!$asset->is_enabled]); return back()->with('success',"{$asset->symbol} is now ".($asset->is_enabled?'enabled':'disabled').' for new positions.'); } }
